	BPSidebarItem *item, *parent;
	_rootSidebarCategory = [BPSidebarItem itemWithTitle:@"" identifier:@"root"];

	parent = [BPSidebarItem itemWithTitle:NSLocalizedString(@"Sidebar_Group_Formulae", nil)
