370	- (NSButton *)makeButtonForItemImage:(NSImage *)image target:(id)target action:(SEL)action
371	{
372		if (image == nil) {
373			return nil;
374		}
375		NSButton *button = [NSButton buttonWithImage:image target:target action:action];
376		[button setBezelStyle:NSBezelStyleRegularSquare];
377		[button setBordered:NO];
378		[button setTranslatesAutoresizingMaskIntoConstraints:NO];
379		if (@available(macOS 11, *)) {
380			[button setSymbolConfiguration:[NSImageSymbolConfiguration configurationWithPointSize:24
381																							  weight:NSFontWeightMedium
382																							   scale:NSImageSymbolScaleMedium]];
383		}
384		[button setImageScaling:NSImageScaleProportionallyUpOrDown];
385		return button;
386	}
